nbsp;&nbsp;(Universidad Paulista, Universidad Católica de São Paulo, Brasil)</td> <td style="text-align: center;"> <p>Internacional</p> </td> </tr> <tr> <td>Grupo de trabajo URBESOM (Grupo de Pesquisa em Culturas Urbanas, Música e Comunicação)&nbsp;<span lang="ES">Universidad Paulista. Brasil&nbsp;</span></td> <td style="text-align: center;"> <p>Internacional</p> </td> </tr> <tr> <td>Asociación Internacional en Estudios de Música popular_ Rama Latinoamericana</td> <td style="text-align: center;"> <p>Internacional</p> </td> </tr><tr> <td>Red de Humanidades Digitales AC (REDHD)</td> <td style="text-align: center;"> <p>Nacional</p> </td> </tr> <tr> <td>RED FEIAL&nbsp;(Red de Formadores en Educación e Interculturalidad en América Latina</td> <td style="text-align: center;"> <p>Internacional</p> </td> </tr> <tr> <td>Consejo&nbsp;Mexicano de Investigación Educativa</td> <td style="text-align: center;"> <p>Nacional</p> </td> </tr> <tr> <td>RED ESIAL&nbsp;Educación Superior y Pueblos Indígenas y Afrodescendientes en América Latina</td> <td style="text-align: center;"> <p>Internacional</p> </td> </tr> <tr> <td>Cátedra UNESCO de Educación Superior y Pueblos Indígenas y Afrodescendientes en América Latina</td> <td style="text-align: center;"> <p>Internacional</p> </td> </tr> </tbody> </table>
